19	/**
20	 * Maps Owner & OwnerDto using Mapstruct
21	 */
22	@Mapper(uses = PetMapper.class)
23	public interface OwnerMapper {
24	
25	    @Mapping(target = "displayName",
26	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
27	    @Mapping(target = "initials",
28	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
29	            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
30	    @Mapping(target = "householdId", expression = "java(householdId(owner))")
31	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
32	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
33	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
34	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
35	    @Mapping(target = "locality", expression = "java(locality(owner))")
36	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
37	    OwnerDto toOwnerDto(Owner owner);
38	
39	    /**
40	     * Derives an owner's preferred contact channel: {@code "EMAIL"} when the owner has a non-blank
41	     * email, otherwise {@code "PHONE"}.
42	     *
43	     * @param owner the owner to derive the contact preference for
44	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
45	     */
46	    default String contactPreference(Owner owner) {
47	        String email = owner.getEmail();
48	        return (email != null && !email.isBlank()) ? "EMAIL" : "PHONE";
49	    }
50	
51	    /**
52	     * Derives an owner's locality from the region-and-hash customer code: the {@code <REGION>}
53	     * segment (everything before the first {@code '-'}) of the owner's {@code customerCode}. Because
54	     * the customer code's region is itself derived from the postcode (falling back to the city), the
55	     * locality now moves with the identity rather than being computed independently. The result is
56	     * {@code "UNKNOWN"} when no customer code is present.
57	     *
58	     * @param owner the owner to derive the locality for
59	     * @return the region segment of the customer code, or {@code "UNKNOWN"}
60	     */
61	    default String locality(Owner owner) {
62	        String code = owner.getCustomerCode();
63	        if (code == null || code.isEmpty()) {
64	            return "UNKNOWN";
65	        }
66	        int dash = code.indexOf('-');
67	        return dash < 0 ? code : code.substring(0, dash);
68	    }
69	
70	    /**
71	     * Derives an owner's numeric membership level, fixed at creation. Starts at {@code 1}, plus
72	     * {@code 1} when an email is present (non-blank), plus {@code 1} when the owner's namesake count
73	     * is {@code 0}, capped at {@code 3} (level {@code 4} is reserved for tenure).
74	     *
75	     * @param owner the owner to derive the membership level for
76	     * @return the membership level, between {@code 1} and {@code 3}
77	     */
78	    default Integer membershipLevel(Owner owner) {
79	        int level = 1;
80	        String email = owner.getEmail();
81	        if (email != null && !email.isBlank()) {
82	            level++;
83	        }
84	        Integer namesakeCount = owner.getNamesakeCount();
85	        if (namesakeCount != null && namesakeCount == 0) {
86	            level++;
87	        }
88	        return Math.min(level, 3);
89	    }
90	
91	    /**
92	     * Derives an owner's membership number, formatted {@code <customerCode>-M<YY>} where
93	     * {@code <customerCode>} is the owner's region-and-hash customer code and {@code YY} is the last
94	     * two digits (zero-padded) of the owner's registration date year (e.g. {@code NSW-1A2B3C4D-M26}).
95	     *
96	     * @param owner the owner to derive the membership number for
97	     * @return the formatted membership number
98	     */
99	    default String membershipNumber(Owner owner) {
100	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
101	        return owner.getCustomerCode() + "-M" + yy;
102	    }
103	
104	    /**
105	     * Derives an owner's check digit: a single Luhn check digit ({@code 0}-{@code 9}) computed over
106	     * the digits contained in the owner's customer code. Non-digit characters in the customer code
107	     * are ignored.
108	     *
109	     * @param owner the owner to derive the check digit for
110	     * @return the Luhn check digit, between {@code 0} and {@code 9}
111	     */
112	    default Integer checkDigit(Owner owner) {
113	        String code = owner.getCustomerCode();
114	        int sum = 0;
115	        boolean dbl = true;
116	        for (int i = code.length() - 1; i >= 0; i--) {
117	            char c = code.charAt(i);
118	            if (c < '0' || c > '9') {
119	                continue;
120	            }
121	            int d = c - '0';
122	            if (dbl) {
123	                d *= 2;
124	                if (d > 9) {
125	                    d -= 9;
126	                }
127	            }
128	            sum += d;
129	            dbl = !dbl;
130	        }
131	        return (10 - (sum % 10)) % 10;
132	    }
133	
134	    /**
135	     * Derives an owner's household identifier: a stable value shared by every owner with the same
136	     * last name and address (compared case-insensitively with collapsed whitespace). Because it is
137	     * derived deterministically from those fields, owners created via the {@code sharesHousehold}
138	     * flag - which by definition have a matching last name and address - receive the same value.
139	     *
140	     * @param owner the owner to derive the household identifier for
141	     * @return a {@code HH-} prefixed identifier, never blank
142	     */
143	    default String householdId(Owner owner) {
144	        String key = normalizeHouseholdField(owner.getLastName()) + ' '
145	            + normalizeHouseholdField(owner.getAddress());
146	        try {
147	            byte[] digest = MessageDigest.getInstance("SHA-256")
148	                .digest(key.getBytes(StandardCharsets.UTF_8));
149	            StringBuilder sb = new StringBuilder("HH-");
150	            for (int i = 0; i < 6; i++) {
151	                sb.append(String.format("%02X", digest[i]));
152	            }
153	            return sb.toString();
154	        }
155	        catch (NoSuchAlgorithmException ex) {
156	            throw new IllegalStateException("SHA-256 not available", ex);
157	        }
158	    }
159	
160	    /**
161	     * Derives an owner's identity key, into which all duplicate detection is consolidated. The key
162	     * is {@code <normalizedTelephone>|<email or empty>|<householdId>}: the owner's (already E.164
163	     * normalized) telephone, its (already lower-cased) email or the empty string when none is held,
164	     * and its {@link #householdId(Owner) household id}. Two owners are duplicates only when their
165	     * whole identity keys are equal; because the telephone is part of the key, household members with
166	     * different telephones have different keys.
167	     *
168	     * @param owner the owner to derive the identity key for
169	     * @return the {@code telephone|email|householdId} identity key
170	     */
171	    default String identityKey(Owner owner) {
172	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
173	        String email = owner.getEmail() == null ? "" : owner.getEmail();
174	        return telephone + '|' + email + '|' + householdId(owner);
175	    }
176	
177	    /**
178	     * Collapses surrounding and internal whitespace and lower-cases a value so household fields can
179	     * be compared case-insensitively with collapsed whitespace. A {@code null} value normalizes to
180	     * the empty string. Mirrors the normalization used when enforcing the household rule on create.
181	     *
182	     * <p>Declared {@code private} so MapStruct does not treat it as an implicit String-to-String
183	     * conversion and apply it to unrelated String properties (last name, address, ...).
184	     */
185	    private String normalizeHouseholdField(String value) {
186	        if (value == null) {
187	            return "";
188	        }
189	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
190	    }
191	
192	    Owner toOwner(OwnerDto ownerDto);
193	
194	    @Mapping(target = "id", ignore = true)
195	    @Mapping(target = "pets", ignore = true)
196	    Owner toOwner(OwnerFieldsDto ownerDto);
197	
198	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
199	
200	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
201	
202	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
203	        OwnerPageDto ownerPageDto = new OwnerPageDto();
204	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
205	        ownerPageDto.setPage(ownerPage.getNumber());
206	        ownerPageDto.setSize(ownerPage.getSize());
207	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
208	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
209	        return ownerPageDto;
210	    }
211	}
